<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { ArrowDownToLine, CheckCircle2, ChevronRight, Eye, FileCheck2, Plus, RefreshCw, Search, SlidersHorizontal, Truck, X } from "lucide-vue-next";
import ContentManager from "./ContentManager.vue";
import {
  assignRelationship, createOrder, deleteArticle, deleteBanner, downloadExport, getAdminArticles, getAftersales, getAnalytics, getBanners, getCommissionRules,
  getCustomerProfile, getCustomers, getIntegrationStatus, getInvoices, getMemberApplications, getOrderDetail, getOrders,
  getPrescriptions, getProducts, getPromoters, getRelationships, getSettings, getWithdrawals, manualPrescription,
  receiveOrder, reviewAftersale as reviewAftersaleApi, reviewMember, reviewPrescription, reviewWithdrawal, saveArticle, saveBanner,
  saveCommissionRule, saveCustomer, saveCustomerTag, saveProduct, savePromoter, saveSettings, shipOrder, deleteProduct, saveProductSku, saveInventoryBatch, reviewInvoice, transferWithdrawal,
  loginStaff, uploadFile, downloadFile,
  settleRewards,
} from "./api";

const props = defineProps<{ active: string; role?: string }>();
const staffRole = computed(() => String(props.role || "admin").toLowerCase());
const isAdmin = computed(() => staffRole.value === "admin");
const canCreate = computed(() => isAdmin.value || (staffRole.value === "pharmacist" && props.active === "prescriptions"));
const labels: Record<string, string> = { products: "商品与库存", orders: "订单与履约", prescriptions: "处方工作台", sales: "销售与奖励", customers: "客户档案", content: "内容中心", settings: "系统设置", analytics: "数据报表" };
const activeTitle = computed(() => labels[props.active] || "工作台");
const loading = ref(false); const notice = ref(""); const query = ref(""); const statusFilter = ref("all"); const orderFrom = ref(""); const orderTo = ref("");
const products = ref<any[]>([]); const orders = ref<any[]>([]); const prescriptions = ref<any[]>([]); const customers = ref<any[]>([]); const articles = ref<any[]>([]); const banners = ref<any[]>([]); const promoters = ref<any[]>([]); const applications = ref<any[]>([]); const relationships = ref<any[]>([]); const rules = ref<any[]>([]); const withdrawals = ref<any[]>([]); const aftersales = ref<any[]>([]); const invoices = ref<any[]>([]); const analytics = ref<any>({ summary: {}, productRank: [], promoterRank: [], daily: [] }); const settings = ref<any>({}); const integrations = ref<any>({});
const prescriptionProducts = computed(() => products.value.filter((item: any) => item.category === "prescription"));
const contentTab = ref("articles"); const detail = ref<any>(null); const detailKind = ref(""); const sensitiveLoading = ref(false);
const authDialog = ref(false); const authForm = ref({ username: "", password: "" });
const prescriptionCustomers = ref<any[]>([]); const patientOptions = ref<any[]>([]); const uploadingPrescription = ref(false); const prescriptionFileName = ref(""); const fileDownloading = ref(false); const uploadingProductImage = ref(false);
const productDialog = ref(false); const articleDialog = ref(false); const orderDialog = ref(false); const rxDialog = ref(false); const promoterDialog = ref(false); const customerDialog = ref(false); const bannerDialog = ref(false); const settingsDialog = ref(false); const cropDialog = ref(false); const cropImage = ref(""); const cropFileName = ref("");
const productForm = ref<any>({ id: "", name: "", category: "daily", price: 0, stock: 0, unit: "件", badge: "新品", rewardRule: "暂不参与", subtitle: "", description: "", registrationNo: "", image: "", active: true, skuName: "", batchNo: "", expiresAt: "" });
const articleForm = ref<any>({ id: "", title: "", tag: "健康科普", summary: "", body: "", published: true, recommended: false });
const orderForm = ref<any>({ customerUserId: "", productId: "", quantity: 1, name: "", phone: "", detail: "" });
const rxForm = ref<any>({ userId: "u-demo", patientId: "", patientName: "", productId: "", itemName: "胆南星直服饮片", validUntil: "", externalId: "", fileKey: "" });
const promoterForm = ref<any>({ id: "", name: "", promoterClass: "sales", userId: "", active: true });
const customerForm = ref<any>({ id: "", name: "", promoter: "", tags: "" });
const bannerForm = ref<any>({ id: "", title: "", imageKey: "", target: "/pages/index/index", active: true, mode: "default", sort: 0 });
const settingsForm = ref<any>({ shippingFreeThreshold: 199, shippingFee: 8, autoCancelMinutes: 30, autoReceiveDays: 7, withdrawThreshold: 500, companyName: "九转健康", servicePhone: "400-000-0000" });
const ruleDialog = ref(false); const relationshipDialog = ref(false);
const ruleForm = ref<any>({ id: "", productId: "", promoterType: "ORDINARY_MEMBER", rate: 0, fixedAmount: 0, enabled: true });
const relationshipForm = ref<any>({ promoterId: "", customerId: "", source: "admin-assignment" });
const productImageMap = import.meta.glob("../../assets/products/*.webp", { eager: true, import: "default", query: "?url" }) as Record<string, string>;

const filteredProducts = computed(() => products.value.filter((row) => !query.value || `${row.name} ${row.id}`.toLowerCase().includes(query.value.toLowerCase())));
const filteredOrders = computed(() => orders.value.filter((row) => { const date = String(row.createdAt || "").slice(0, 10); return (!query.value || `${row.orderNo} ${row.userId} ${row.address?.name || ""}`.toLowerCase().includes(query.value.toLowerCase())) && (statusFilter.value === "all" || row.status === statusFilter.value) && (!orderFrom.value || date >= orderFrom.value) && (!orderTo.value || date <= orderTo.value); }));
const filteredPrescriptions = computed(() => prescriptions.value.filter((row) => (!query.value || `${row.id} ${row.patientName} ${row.itemName || ""}`.toLowerCase().includes(query.value.toLowerCase())) && (statusFilter.value === "all" || row.status === statusFilter.value)));
const filteredCustomers = computed(() => customers.value.filter((row) => !query.value || `${row.name} ${row.promoter} ${(row.tags || []).join(" ")}`.toLowerCase().includes(query.value.toLowerCase())));
const productQuantity = computed(() => (analytics.value.productRank || []).reduce((sum: number, row: any) => sum + Number(row.quantity || 0), 0));
const statusText = (value: string) => { const mapped = ({ pending_payment: "待支付", paid: "待发货", shipped: "待收货", completed: "已完成", cancelled: "已取消", pending_review: "待审核", approved: "审核通过", rejected: "已拒绝", eligible: "可结算", settled: "已结算", reversed: "已扣回", pending: "待处理", processing: "处理中", refunding: "退款中", issued: "已开具", pending_transfer: "待打款", held: "售后冻结" } as Record<string, string>)[value]; return mapped || (/^[\u4e00-\u9fff]/.test(String(value || "")) ? value : (value ? "待处理" : "未知")); };
const statusClass = (value: string) => ({ paid: "teal", shipped: "teal", completed: "slate", pending_payment: "amber", pending_review: "amber", approved: "teal", rejected: "plum", cancelled: "slate", eligible: "teal", settled: "teal", reversed: "plum" } as Record<string, string>)[value] || "slate";
const modeText = (value: string) => ({ real: "真实接口", manual: "人工处理", memory: "本地数据", prisma: "数据库" } as Record<string, string>)[value] || value || "未配置";
const levelText = (value: string) => ({ STAFF: "销售人员", SENIOR_MEMBER: "高级会员", ORDINARY_MEMBER: "普通会员" } as Record<string, string>)[value] || value || "未设置";
const promoterClassText = (row: any) => row.promoterClassText || (String(row.type || "").toLowerCase() === "sales" || String(row.level || "").toUpperCase() === "STAFF" ? "销售人员（高级会员）" : "会员");
const sourceText = (value: string) => ({ "admin-assignment": "后台分配", "qr-code": "二维码", "article-share": "文章分享", "share-link": "分享链接", "sales-order": "代客下单" } as Record<string, string>)[value] || value || "其他来源";
const rateText = (row: any) => `${((Number(row.rateBps ?? Number(row.rate || 0) * 10000)) / 100).toFixed(2)}%`;
const money = (value: unknown) => `¥${Number(value || 0).toLocaleString("zh-CN", { minimumFractionDigits: 2 })}`;
const dateText = (value: string) => value ? new Date(value).toLocaleString("zh-CN", { hour12: false }) : "-";
const productImage = (row: any) => { const key = String(row.image || row.imageKey || ""); const file = key.split("/").pop(); return file ? productImageMap[`../../assets/products/${file}`] || key : ""; };

function toast(message: string) { notice.value = message; window.setTimeout(() => { notice.value = ""; }, 2400); }
async function perform(action: () => Promise<unknown>, message: string) { try { await action(); toast(message); await load(); return true; } catch (error: any) { toast(error?.message || "操作失败，请检查服务端日志"); return false; } }
const analyticsFilters = ref({ from: "", to: "", category: "all", productId: "", promoterId: "" });
async function load() {
  loading.value = true; query.value = ""; statusFilter.value = "all";
  try {
    if (props.active === "products") products.value = await getProducts("includeInactive=1");
    if (props.active === "orders") [orders.value, aftersales.value, invoices.value] = await Promise.all([getOrders(), getAftersales(), getInvoices()]);
    if (props.active === "prescriptions") { prescriptions.value = await getPrescriptions(); prescriptionCustomers.value = isAdmin.value ? await getCustomers() : []; }
    if (props.active === "sales") [promoters.value, applications.value, relationships.value, rules.value, withdrawals.value] = await Promise.all([getPromoters(), getMemberApplications(), getRelationships(), getCommissionRules(), getWithdrawals()]);
    if (props.active === "customers") customers.value = await getCustomers();
    if (props.active === "content") [articles.value, banners.value] = await Promise.all([getAdminArticles(), getBanners()]);
    if (props.active === "settings") [settings.value, integrations.value] = await Promise.all([getSettings(), getIntegrationStatus()]);
    if (props.active === "analytics") analytics.value = await getAnalytics(Object.fromEntries(Object.entries(analyticsFilters.value).filter(([, value]) => value)));
  } catch (error: any) { if (error?.status === 401) authDialog.value = true; else toast("当前模块接口暂不可用，请检查 API 服务"); }
  finally { loading.value = false; }
}
watch(() => props.active, load); onMounted(load);
function openProduct(row?: any) { productForm.value = row ? { ...productForm.value, ...row, price: Number(row.price ?? (Number(row.priceFen || 0) / 100)), skuName: row.skuName || row.unit || "", batchNo: row.batchNo || "", expiresAt: row.expiresAt || "" } : { id: "", name: "", category: "daily", price: 0, stock: 0, unit: "件", badge: "新品", rewardRule: "暂不参与", subtitle: "", description: "", registrationNo: "", image: "", active: true, skuName: "", batchNo: "", expiresAt: "" }; productDialog.value = true; }
function openArticle(row?: any) { articleForm.value = row ? { ...articleForm.value, ...row, recommended: Boolean(row.recommended) } : { id: "", title: "", tag: "健康科普", summary: "", body: "", published: true, recommended: false }; articleDialog.value = true; }
function openOrderForm() { orderForm.value = { customerUserId: "", productId: products.value[0]?.id || "", quantity: 1, name: "", phone: "", detail: "" }; orderDialog.value = true; }
function openPrescription() { rxForm.value = { userId: prescriptionCustomers.value[0]?.id || "", patientId: "", patientName: "", productId: products.value.find((item: any) => item.category === "prescription")?.id || "", itemName: "胆南星直服饮片", validUntil: new Date(Date.now() + 30 * 86400000).toISOString().slice(0, 10), externalId: "", fileKey: "" }; patientOptions.value = []; prescriptionFileName.value = ""; rxDialog.value = true; }
function syncPrescriptionProduct() { const product = products.value.find((item: any) => item.id === rxForm.value.productId); if (product) rxForm.value.itemName = product.name; }
async function loadPatients() { if (!rxForm.value.userId) return toast("请先填写用户编号"); try { const profile = await getCustomerProfile(String(rxForm.value.userId)); patientOptions.value = Array.isArray(profile?.patients) ? profile.patients : []; if (!patientOptions.value.length) toast("该用户暂无实名就诊人"); else { rxForm.value.patientId = patientOptions.value[0].id || ""; rxForm.value.patientName = patientOptions.value[0].name || ""; toast("已读取就诊人"); } } catch (error: any) { toast(error?.message || "就诊人读取失败"); } }
async function uploadPrescriptionFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; if (!rxForm.value.userId) return toast("请先填写用户编号"); uploadingPrescription.value = true; try { const result = await uploadFile(file, "prescription", String(rxForm.value.userId)); rxForm.value.fileKey = result.fileKey; prescriptionFileName.value = file.name; toast("处方凭证上传成功"); } catch (error: any) { (event.target as HTMLInputElement).value = ""; toast(error?.message || "处方凭证上传失败"); } finally { uploadingPrescription.value = false; } }
async function uploadProductImage(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; uploadingProductImage.value = true; try { const result = await uploadFile(file, "product"); productForm.value.image = result.fileKey; toast("商品图片上传成功"); } catch (error: any) { (event.target as HTMLInputElement).value = ""; toast(error?.message || "商品图片上传失败"); } finally { uploadingProductImage.value = false; } }
async function downloadPrescriptionFile(fileKey: string) { if (!fileKey) return; fileDownloading.value = true; try { await downloadFile(fileKey, "处方凭证"); } catch (error: any) { toast(error?.message || "凭证读取失败"); } finally { fileDownloading.value = false; } }
function openPromoter(row?: any) {
  promoterForm.value = row
    ? { id: row.id, name: row.name || "", promoterClass: String(row.type || "").toLowerCase() === "sales" || String(row.level || "").toUpperCase() === "STAFF" ? "sales" : "member", userId: row.userId || "", active: row.active !== false }
    : { id: "", name: "", promoterClass: "sales", userId: "", active: true };
  promoterDialog.value = true;
}
function openCustomer(row?: any) { if (!row) { customerForm.value = { id: "", name: "", promoter: "", tags: "" }; customerDialog.value = true; return; } getCustomerProfile(row.id).then((data) => { detail.value = data; detailKind.value = "customer"; }).catch((error: any) => toast(error?.message || "客户档案加载失败")); }
async function openOrderDetail(row: any) { try { detail.value = await getOrderDetail(row.id); } catch { detail.value = row; } detailKind.value = "order"; }
async function viewSensitiveCustomer() { const customerId = detail.value?.customer?.id || detail.value?.id; if (!customerId) return; const reason = window.prompt("请填写查看完整健康信息的业务原因"); if (!reason?.trim()) return toast("查看敏感信息必须填写原因"); sensitiveLoading.value = true; try { detail.value = await getCustomerProfile(customerId, true, reason.trim()); toast("已记录敏感信息查看审计"); } catch (error: any) { toast(error?.message || "无法查看完整健康信息"); } finally { sensitiveLoading.value = false; } }
function openBanner(row?: any) { bannerForm.value = row ? { ...bannerForm.value, ...row, mode: row.mode || "custom", sort: Number(row.sort || 0) } : { id: "", title: "", imageKey: "", target: "/pages/index/index", active: true, mode: "default", sort: 0 }; bannerDialog.value = true; }
function openRule(row?: any) { ruleForm.value = row ? { ...ruleForm.value, ...row } : { id: "", productId: products.value[0]?.id || "", promoterType: "ORDINARY_MEMBER", rate: 0, fixedAmount: 0, enabled: true }; ruleDialog.value = true; }
function openRelationship() { relationshipForm.value = { promoterId: promoters.value[0]?.id || "", customerId: customers.value[0]?.id || "", source: "admin-assignment" }; relationshipDialog.value = true; }
function openSettings() { settingsForm.value = { ...settingsForm.value, shippingFreeThreshold: Number(settings.value.shippingFreeThresholdFen || 19900) / 100, shippingFee: Number(settings.value.shippingFeeFen || 800) / 100, autoCancelMinutes: Number(settings.value.autoCancelMinutes || 30), autoReceiveDays: Number(settings.value.autoReceiveDays || 7), withdrawThreshold: Number(settings.value.withdrawThresholdFen || 50000) / 100, companyName: String(settings.value.companyName || "九转健康"), servicePhone: String(settings.value.servicePhone || "400-000-0000") }; settingsDialog.value = true; }
function createRecord() { if (props.active === "products") openProduct(); else if (props.active === "orders") openOrderForm(); else if (props.active === "prescriptions") openPrescription(); else if (props.active === "sales") openPromoter(); else if (props.active === "customers") openCustomer(); else if (props.active === "content") contentTab.value === "articles" ? openArticle() : openBanner(); else if (props.active === "settings") openSettings(); else toast("数据报表通过筛选和导出使用"); }
async function submitProduct() {
  const payload = { ...productForm.value, priceFen: Math.round(Number(productForm.value.price || 0) * 100) };
  const saved = await perform(async () => {
    const saved: any = await saveProduct(payload);
    const productId = String(saved?.id || productForm.value.id || "");
    if (productId && productForm.value.skuName) await saveProductSku(productId, { name: productForm.value.skuName, priceFen: payload.priceFen, stock: Number(productForm.value.stock || 0), active: productForm.value.active !== false });
    if (productId && (productForm.value.batchNo || productForm.value.expiresAt)) await saveInventoryBatch({ productId, batchNo: productForm.value.batchNo, quantity: Number(productForm.value.stock || 0), expiresAt: productForm.value.expiresAt || undefined });
  }, "商品已保存");
  if (saved) productDialog.value = false;
}
async function removeProduct(row: any) { if (!window.confirm(`确定删除商品“${row.name}”吗？已产生订单的商品会自动下架。`)) return; await perform(() => deleteProduct(row.id), "商品处理完成"); }
async function submitArticle() { if (await perform(() => saveArticle(articleForm.value), "文章已保存")) articleDialog.value = false; }
async function submitOrder() { if (await perform(() => createOrder({ customerUserId: orderForm.value.customerUserId || undefined, items: [{ productId: orderForm.value.productId, quantity: Number(orderForm.value.quantity) }], address: { name: orderForm.value.name, phone: orderForm.value.phone, detail: orderForm.value.detail } }), "人工订单已创建")) orderDialog.value = false; }
async function submitPrescription() { if (await perform(() => manualPrescription(rxForm.value), "处方已录入")) rxDialog.value = false; }
async function submitPromoter() { if (await perform(() => savePromoter({ ...promoterForm.value, type: promoterForm.value.promoterClass }), "推广人已保存")) promoterDialog.value = false; }
async function submitCustomer() { if (await perform(() => saveCustomer({ ...customerForm.value, tags: String(customerForm.value.tags || "").split(",").map((item) => item.trim()).filter(Boolean) }), "客户档案已保存")) customerDialog.value = false; }
async function submitBanner() { if (await perform(() => saveBanner(bannerForm.value), "轮播已保存")) bannerDialog.value = false; }
async function removeArticle(row: any) { if (!window.confirm("确定删除这篇文章吗？")) return; await perform(() => deleteArticle(row.id), "文章已删除"); }
async function removeBanner(row: any) { if (!window.confirm("确定删除这张轮播图吗？")) return; await perform(() => deleteBanner(row.id), "轮播已删除"); }
async function reviewAftersale(id: string, action: string) { if (action === "refund") { const transactionId = window.prompt("请输入已支付订单的微信支付流水号"); if (!transactionId?.trim()) return toast("未填写支付流水，未改变售后状态"); return perform(() => reviewAftersaleApi(id, action, { transactionId: transactionId.trim() }), "退款已进入处理队列"); } return perform(() => reviewAftersaleApi(id, action), action === "approve" ? "售后已通过" : "售后已驳回"); }
function chooseBannerFile(event: Event) { const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (!file) return; cropFileName.value = file.name; const reader = new FileReader(); reader.onload = () => { cropImage.value = String(reader.result || ""); cropDialog.value = true; }; reader.readAsDataURL(file); }
function applyCrop() { bannerForm.value.imageKey = cropImage.value; bannerForm.value.mode = "custom"; cropDialog.value = false; toast("图片已按手机轮播比例裁剪"); }
async function submitRule() { if (await perform(() => saveCommissionRule(ruleForm.value), "奖励规则已保存")) ruleDialog.value = false; }
async function submitRelationship() { if (await perform(() => assignRelationship(relationshipForm.value), "隶属关系已保存")) relationshipDialog.value = false; }
async function recordWithdrawal(row: any) { const transactionId = window.prompt("请输入实际打款凭证号"); if (!transactionId?.trim()) return toast("未填写打款凭证，未改变提现状态"); await perform(() => transferWithdrawal(row.id, transactionId.trim()), "已记录人工打款凭证"); }
async function refreshAnalytics() { try { analytics.value = await getAnalytics(Object.fromEntries(Object.entries(analyticsFilters.value).filter(([, value]) => value))); toast("报表已刷新"); } catch (error: any) { toast(error?.message || "报表加载失败"); } }
async function submitSettings() { if (await perform(() => saveSettings({ shippingFreeThresholdFen: Math.round(Number(settingsForm.value.shippingFreeThreshold) * 100), shippingFeeFen: Math.round(Number(settingsForm.value.shippingFee) * 100), autoCancelMinutes: Number(settingsForm.value.autoCancelMinutes), autoReceiveDays: Number(settingsForm.value.autoReceiveDays), withdrawThresholdFen: Math.round(Number(settingsForm.value.withdrawThreshold) * 100), companyName: settingsForm.value.companyName, servicePhone: settingsForm.value.servicePhone }), "设置已保存")) settingsDialog.value = false; }
async function processOrder(row: any) { if (row.status === "paid") return perform(() => shipOrder(row.id), "订单已发货"); if (row.status === "shipped") return perform(() => receiveOrder(row.id), "已确认收货"); detail.value = row; detailKind.value = "order"; }
async function reviewRx(row: any) { await perform(() => reviewPrescription(row.id, { approved: true, itemName: row.itemName || "待确认", validUntil: row.validUntil || new Date().toISOString().slice(0, 10) }), "处方已审核通过"); }
async function rejectRx(row: any) { await perform(() => reviewPrescription(row.id, { approved: false, reason: "处方资料需要补充" }), "处方已驳回"); }
async function exportModule() { const basePath = props.active === "sales" ? "/v1/admin/sales/export.xlsx" : props.active === "analytics" ? "/v1/admin/reports/export.xlsx" : "/v1/admin/customers/export.xlsx"; const filters = props.active === "analytics" ? new URLSearchParams(Object.fromEntries(Object.entries(analyticsFilters.value).filter(([, value]) => value))) : new URLSearchParams(); const path = filters.toString() ? `${basePath}?${filters.toString()}` : basePath; await downloadExport(path, `${props.active}.xlsx`); toast("导出文件已下载"); }
async function login() { try { await loginStaff(authForm.value.username, authForm.value.password); authDialog.value = false; toast("后台登录成功"); await load(); } catch { toast("账号或密码错误"); } }
</script>

<template>
  <ContentManager v-if="props.active === 'content'" />
  <div v-else class="enterprise-workspace">
    <div v-if="notice" class="enterprise-toast">{{ notice }}</div>
    <header class="enterprise-head"><div><p class="eyebrow">运营 / {{ activeTitle.toUpperCase() }}</p><h2>{{ activeTitle }}</h2><p class="enterprise-subtitle">查询、编辑、审核和导出都在同一张业务工作台完成。</p></div><div class="enterprise-actions"><button v-if="isAdmin" class="ghost-button" @click="exportModule"><ArrowDownToLine :size="15" />导出</button><button v-if="canCreate" class="primary-small" @click="createRecord"><Plus :size="15" />新增记录</button></div></header>
    <div class="enterprise-toolbar"><div class="toolbar-search"><Search :size="15" /><input v-model="query" placeholder="搜索编号、名称、客户或标签" /></div><select v-if="props.active === 'orders' || props.active === 'prescriptions'" v-model="statusFilter" class="filter-select"><option value="all">全部状态</option><option v-if="props.active === 'orders'" value="pending_payment">待支付</option><option v-if="props.active === 'orders'" value="paid">待发货</option><option v-if="props.active === 'orders'" value="shipped">待收货</option><option v-if="props.active === 'orders'" value="completed">已完成</option><option v-if="props.active === 'prescriptions'" value="pending_review">待审核</option><option v-if="props.active === 'prescriptions'" value="approved">审核通过</option></select><label v-if="props.active === 'orders'" class="date-filter">起始日期<input v-model="orderFrom" type="date" /></label><label v-if="props.active === 'orders'" class="date-filter">结束日期<input v-model="orderTo" type="date" /></label><button class="filter-button" @click="load"><RefreshCw :size="14" />{{ loading ? "同步中" : "刷新" }}</button></div>

    <section v-if="props.active === 'products'" class="enterprise-panel"><div class="panel-heading"><div><p class="panel-kicker">商品目录</p><h2>商品、规格与库存</h2></div><span class="panel-count">{{ filteredProducts.length }} 个商品</span></div><div class="data-table wide product-table"><div class="table-head"><span>商品</span><span>分类</span><span>库存</span><span>售价</span><span>有效期</span><span>状态</span><span>操作</span></div><div v-for="row in filteredProducts" :key="row.id" class="table-row"><span class="product-cell"><span class="table-thumb"><img v-if="productImage(row)" :src="productImage(row)" alt="" /><span v-else>{{ row.category === 'prescription' ? '处' : '养' }}</span></span><span><b>{{ row.name }}</b><small>{{ row.unit || '未设置规格' }} · {{ row.id }}</small></span></span><span>{{ row.category === 'prescription' ? '处方饮片' : '药食同源' }}</span><span :class="{ 'low-stock': Number(row.stock) < 50 }">{{ row.stock }} 件<small v-if="row.skuCount">{{ row.skuCount }} 个规格</small></span><span class="money">{{ money(row.price) }}</span><span :class="{ 'low-stock': row.expiryWarning }">{{ row.expiryWarning ? '临近有效期' : '正常' }}</span><em class="status-pill" :class="row.active === false ? 'slate' : 'teal'">{{ row.active === false ? '已下架' : '销售中' }}</em><span class="row-actions"><button v-if="isAdmin" class="row-action" @click="openProduct(row)">编辑 <ChevronRight :size="13" /></button><button v-if="isAdmin" class="row-action danger-text" @click="removeProduct(row)">删除</button><span v-if="!isAdmin" class="muted-action">只读</span></span></div><div v-if="!filteredProducts.length" class="empty-list">暂无商品，请新增一条记录。</div></div></section>

    <section v-else-if="props.active === 'orders'" class="enterprise-panel"><div class="panel-heading"><div><p class="panel-kicker">订单履约</p><h2>订单查询与履约</h2></div><span class="panel-count">{{ filteredOrders.length }} 笔</span></div><div class="data-table wide"><div class="table-head"><span>订单号</span><span>客户</span><span>下单时间</span><span>金额</span><span>状态</span><span>操作</span></div><div v-for="row in filteredOrders" :key="row.id" class="table-row"><button class="table-link" @click="openOrderDetail(row)"><b>{{ row.orderNo }}</b><small>{{ row.id }}</small></button><span>{{ row.address?.name || row.userId || '-' }}</span><span>{{ dateText(row.createdAt) }}</span><span class="money">{{ money(row.totalAmount) }}</span><em class="status-pill" :class="statusClass(row.status)">{{ row.statusText || statusText(row.status) }}</em><button class="row-action" @click="processOrder(row)">{{ row.status === 'paid' ? '发货' : row.status === 'shipped' ? '收货' : '详情' }} <ChevronRight :size="13" /></button></div><div v-if="!filteredOrders.length" class="empty-list">暂无匹配订单。</div></div></section>

    <section v-else-if="props.active === 'prescriptions'" class="enterprise-panel"><div class="panel-heading"><div><p class="panel-kicker">处方审核</p><h2>处方录入与审核</h2></div><span class="panel-count amber-count">{{ filteredPrescriptions.filter((item) => item.status === 'pending_review').length }} 待审核</span></div><div class="data-table wide"><div class="table-head"><span>处方</span><span>就诊人</span><span>来源</span><span>有效期</span><span>状态</span><span>操作</span></div><div v-for="row in filteredPrescriptions" :key="row.id" class="table-row"><button class="table-link" @click="detail = row; detailKind = 'prescription'"><b>{{ row.itemName || '待药师确认' }}</b><small>{{ row.id }}</small></button><span>{{ row.patientName || '-' }}</span><span>{{ row.source === 'offline' ? '线下上传' : '互联网医院' }}</span><span>{{ row.validUntil || '未设置' }}</span><em class="status-pill" :class="statusClass(row.status)">{{ row.statusText || statusText(row.status) }}</em><span class="row-actions"><button v-if="row.status === 'pending_review'" class="row-action" @click="reviewRx(row)">通过 <CheckCircle2 :size="13" /></button><button v-if="row.status === 'pending_review'" class="row-action danger-text" @click="rejectRx(row)">驳回</button><button class="row-action" @click="detail = row; detailKind = 'prescription'"><Eye :size="13" />查看</button></span></div><div v-if="!filteredPrescriptions.length" class="empty-list">暂无处方记录。</div></div></section>

    <section v-else-if="props.active === 'sales'" class="enterprise-panel"><div class="panel-heading"><div><p class="panel-kicker">推广与结算</p><h2>推广人、会员与奖励</h2></div><div class="panel-actions"><button class="ghost-button" @click="perform(() => settleRewards(), '奖励周结算已执行')">每周结算</button><span class="panel-count">{{ applications.filter((item) => item.status === 'pending').length }} 个待审核</span></div></div><div class="enterprise-grid"><div class="enterprise-card"><b>推广人</b><strong>{{ promoters.length }}</strong><small>销售人员与会员</small></div><div class="enterprise-card warm"><b>会员申请</b><strong>{{ applications.filter((item) => item.status === 'pending').length }}</strong><small>审核通过后可推广</small></div><div class="enterprise-card plum"><b>提现记录</b><strong>{{ withdrawals.length }}</strong><small>可导出财务复核</small></div></div><div class="subsection-head"><h3>推广人维护</h3><button class="text-button" @click="openPromoter()"><Plus :size="14" />新增推广人</button></div><div class="data-table wide"><div class="table-head"><span>名称</span><span>身份</span><span>客户数</span><span>状态</span><span>用户编号</span><span>操作</span></div><div v-for="row in promoters" :key="row.id" class="table-row"><span><b>{{ row.name }}</b><small>{{ row.id }}</small></span><span>{{ promoterClassText(row) }}</span><span>{{ customers.filter((item) => item.promoter === row.id).length }}</span><em class="status-pill" :class="row.active === false ? 'slate' : 'teal'">{{ row.active === false ? '停用' : '正常' }}</em><span>{{ row.userId || '-' }}</span><button class="row-action" @click="openPromoter(row)">编辑 <ChevronRight :size="13" /></button></div></div><div class="split-grid"><div><div class="subsection-head"><h3>会员申请</h3></div><div v-for="row in applications" :key="row.id" class="compact-row"><span><b>{{ row.name }}</b><small>{{ row.phone || row.userId }} · {{ dateText(row.createdAt) }}</small></span><em class="status-pill" :class="statusClass(row.status)">{{ row.statusText || statusText(row.status) }}</em><span v-if="row.status === 'pending'" class="row-actions"><button class="row-action" @click="perform(() => reviewMember(row.id, true), '会员已通过')">通过 <CheckCircle2 :size="13" /></button><button class="row-action danger-text" @click="perform(() => reviewMember(row.id, false), '会员申请已驳回')">驳回</button></span></div></div><div><div class="subsection-head"><h3>提现审核</h3><button class="text-button" @click="exportModule"><ArrowDownToLine :size="14" />导出</button></div><div v-for="row in withdrawals" :key="row.id" class="compact-row"><span><b>{{ row.userId }}</b><small>{{ dateText(row.createdAt) }}</small></span><strong>{{ money(row.amount) }}</strong><span class="row-actions"><button v-if="row.status === 'pending_review' || row.status === 'pending'" class="row-action" @click="perform(() => reviewWithdrawal(row.id, true), '提现已审核，等待打款')">审核通过</button><button v-if="row.status === 'approved'" class="row-action" @click="recordWithdrawal(row)">记录打款</button></span></div></div></div></section>

    <section v-else-if="props.active === 'customers'" class="enterprise-panel"><div class="panel-heading"><div><p class="panel-kicker">客户档案</p><h2>客户档案与健康信息</h2></div><span class="panel-count">{{ filteredCustomers.length }} 位客户</span></div><div class="data-table wide"><div class="table-head"><span>客户</span><span>推广人</span><span>最近购买</span><span>累计金额</span><span>标签</span><span>操作</span></div><div v-for="row in filteredCustomers" :key="row.id" class="table-row"><span class="product-cell"><span class="table-thumb">{{ row.name?.slice(0, 1) }}</span><span><b>{{ row.name }}</b><small>{{ row.id }}</small></span></span><span>{{ row.promoter || '公司归属' }}</span><span>{{ row.lastOrder || '-' }}</span><span class="money">{{ money(row.amount) }}</span><span><em v-for="tag in row.tags || []" :key="tag" class="tag-pill">{{ tag }}</em></span><button class="row-action" @click="openCustomer(row)">查看档案 <Eye :size="13" /></button></div><div v-if="!filteredCustomers.length" class="empty-list">暂无客户档案。</div></div></section>

    <section v-else-if="false" class="enterprise-panel" aria-hidden="true"></section>

    <section v-else-if="props.active === 'settings'" class="enterprise-panel settings-view"><div class="panel-heading"><div><p class="panel-kicker">管理中心</p><h2>业务规则与集成状态</h2></div></div><div class="settings-grid"><button class="setting-card" @click="settingsDialog = true"><SlidersHorizontal :size="20" /><div><b>业务规则</b><small>运费、自动任务、提现门槛和公司资料</small></div><ChevronRight :size="17" /></button><div class="setting-card"><b>微信支付</b><small>{{ modeText(integrations.wechatPayment) }} · 数据仓库 {{ modeText(integrations.repository) }}</small><CheckCircle2 :size="17" /></div><div class="setting-card"><b>第三方服务</b><small>医院 {{ modeText(integrations.hospital) }} · 发票 {{ modeText(integrations.invoice) }} · 物流 {{ modeText(integrations.logistics) }}</small><CheckCircle2 :size="17" /></div><div class="setting-card"><b>审计与导出</b><small>所有后台写入都会记录操作人和资源</small><ArrowDownToLine :size="17" /></div></div></section>

    <section v-else-if="props.active === 'analytics'" class="enterprise-panel"><div class="panel-heading"><div><p class="panel-kicker">数据报表</p><h2>销售与商品数据</h2></div><div class="panel-actions"><button class="ghost-button" @click="refreshAnalytics"><RefreshCw :size="14" />刷新报表</button><button class="ghost-button" @click="exportModule"><ArrowDownToLine :size="14" />导出报表</button></div></div><div class="report-filters"><label>开始日期<input v-model="analyticsFilters.from" type="date" /></label><label>结束日期<input v-model="analyticsFilters.to" type="date" /></label><label>商品板块<select v-model="analyticsFilters.category"><option value="all">全部板块</option><option value="daily">药食同源</option><option value="prescription">处方饮片</option></select></label><label>推广人编号<input v-model="analyticsFilters.promoterId" placeholder="可选" /></label><button class="primary-small" @click="refreshAnalytics">应用筛选</button></div><div class="enterprise-grid"><div class="enterprise-card"><b>订单金额</b><strong>{{ money(analytics.summary?.salesAmount) }}</strong><small>{{ analytics.summary?.orders || 0 }} 笔订单</small></div><div class="enterprise-card warm"><b>商品销量</b><strong>{{ productQuantity }}</strong><small>按商品排行</small></div><div class="enterprise-card plum"><b>奖励总额</b><strong>{{ money(analytics.summary?.commissions) }}</strong><small>含待生效和已结算</small></div></div><div class="split-grid"><div><div class="subsection-head"><h3>商品排行</h3></div><div v-for="row in analytics.productRank || []" :key="row.productId" class="compact-row"><span><b>{{ row.name }}</b><small>{{ row.quantity }} 件</small></span><strong>{{ money(row.amount) }}</strong></div><div v-if="!(analytics.productRank || []).length" class="empty-list">当前筛选暂无商品数据。</div></div><div><div class="subsection-head"><h3>推广人排行</h3></div><div v-for="row in analytics.promoterRank || []" :key="row.promoterId" class="compact-row"><span><b>{{ row.name }}</b><small>{{ row.orders }} 笔订单</small></span><strong>{{ money(row.amount) }}</strong></div><div v-if="!(analytics.promoterRank || []).length" class="empty-list">当前筛选暂无推广数据。</div></div></div></section>

    <div v-if="productDialog" class="dialog-backdrop" @click.self="productDialog = false"><form class="dialog-card large-dialog" @submit.prevent="submitProduct"><div class="dialog-head"><h2>{{ productForm.id ? '编辑商品' : '新增商品' }}</h2><button type="button" class="icon-button" @click="productDialog = false"><X :size="16" /></button></div><div class="dialog-grid"><label>商品名称<input v-model="productForm.name" required /></label><label>分类<select v-model="productForm.category"><option value="daily">药食同源</option><option value="prescription">处方饮片</option></select></label></div><div class="dialog-grid"><label>售价（元）<input v-model.number="productForm.price" type="number" min="0" step="0.01" /></label><label>库存数量<input v-model.number="productForm.stock" type="number" min="0" /></label></div><div class="dialog-grid"><label>规格名称<input v-model="productForm.skuName" placeholder="例如：净含量 100 克" required /></label><label>商品单位<input v-model="productForm.unit" required /></label></div><div class="dialog-grid"><label>批次编号<input v-model="productForm.batchNo" placeholder="录入批次后可追踪有效期" /></label><label>有效期<input v-model="productForm.expiresAt" type="date" /></label></div><div class="dialog-grid"><label>奖励规则<input v-model="productForm.rewardRule" placeholder="例如：普通会员 6%" /></label><label>批准文号<input v-model="productForm.registrationNo" /></label></div><label>商品说明<textarea v-model="productForm.description" rows="3"></textarea></label><label>商品图片<input type="file" accept="image/png,image/jpeg,image/webp" @change="uploadProductImage" /><span class="form-help">{{ uploadingProductImage ? '图片上传中' : (productForm.image ? '已上传图片' : '可选，支持图片文件') }}</span></label><label class="dialog-check"><input v-model="productForm.active" type="checkbox" /> 上架销售</label><p class="form-help">保存商品时会同步规格和批次；有效期会用于后台预警。</p><div class="dialog-actions"><button type="button" class="ghost-button" @click="productDialog = false">取消</button><button type="submit" class="primary-small">保存商品</button></div></form></div>
    <div v-if="articleDialog" class="dialog-backdrop" @click.self="articleDialog = false"><form class="dialog-card" @submit.prevent="submitArticle"><div class="dialog-head"><h2>{{ articleForm.id ? '编辑文章' : '新增文章' }}</h2><button type="button" class="icon-button" @click="articleDialog = false"><X :size="16" /></button></div><label>标题<input v-model="articleForm.title" required /></label><div class="dialog-grid"><label>标签<input v-model="articleForm.tag" /></label><label>摘要<input v-model="articleForm.summary" /></label></div><label>正文<textarea v-model="articleForm.body" rows="8" required></textarea></label><label class="dialog-check"><input v-model="articleForm.published" type="checkbox" /> 发布到小程序</label><div class="dialog-actions"><button type="button" class="ghost-button" @click="articleDialog = false">取消</button><button type="submit" class="primary-small">保存文章</button></div></form></div>
    <div v-if="orderDialog" class="dialog-backdrop" @click.self="orderDialog = false"><form class="dialog-card" @submit.prevent="submitOrder"><div class="dialog-head"><h2>创建人工订单</h2><button type="button" class="icon-button" @click="orderDialog = false"><X :size="16" /></button></div><div class="dialog-grid"><label>客户用户编号<input v-model="orderForm.customerUserId" /></label><label>商品<select v-model="orderForm.productId"><option v-for="item in products" :key="item.id" :value="item.id">{{ item.name }}</option></select></label></div><label>数量<input v-model.number="orderForm.quantity" type="number" min="1" /></label><div class="dialog-grid"><label>收货人<input v-model="orderForm.name" required /></label><label>手机号<input v-model="orderForm.phone" required /></label></div><label>收货地址<input v-model="orderForm.detail" required /></label><div class="dialog-actions"><button type="button" class="ghost-button" @click="orderDialog = false">取消</button><button type="submit" class="primary-small">创建订单</button></div></form></div>
    <div v-if="rxDialog" class="dialog-backdrop" @click.self="rxDialog = false"><form class="dialog-card" @submit.prevent="submitPrescription"><div class="dialog-head"><h2>人工录入处方</h2><button type="button" class="icon-button" @click="rxDialog = false"><X :size="16" /></button></div><div class="dialog-grid"><label>用户编号<select v-if="prescriptionCustomers.length" v-model="rxForm.userId" @change="loadPatients"><option value="">请选择用户</option><option v-for="customer in prescriptionCustomers" :key="customer.id" :value="customer.id">{{ customer.name }}（{{ customer.id }}）</option></select><input v-else v-model="rxForm.userId" required placeholder="输入用户编号" /></label><label>就诊人<select v-if="patientOptions.length" v-model="rxForm.patientName" required><option v-for="patient in patientOptions" :key="patient.name" :value="patient.name">{{ patient.name }}{{ patient.relation ? `（${patient.relation}）` : '' }}</option></select><span v-else class="patient-picker"><input v-model="rxForm.patientName" required placeholder="先读取实名就诊人" /><button type="button" class="ghost-button" @click="loadPatients">读取就诊人</button></span></label></div><div class="dialog-grid"><label>处方商品<select v-model="rxForm.productId" required @change="syncPrescriptionProduct"><option v-for="item in prescriptionProducts" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>有效期<input v-model="rxForm.validUntil" type="date" required /></label></div><label>处方品种<input v-model="rxForm.itemName" required /></label><label>医院处方编号<input v-model="rxForm.externalId" /></label><label>上传处方凭证<input type="file" accept="image/png,image/jpeg,image/webp,application/pdf" required @change="uploadPrescriptionFile" /><span class="form-help">{{ uploadingPrescription ? '凭证上传中' : (prescriptionFileName ? `已上传：${prescriptionFileName}` : '必须上传图片或PDF凭证') }}</span></label><p class="form-help">有效期必须晚于今天；凭证会绑定用户并记录下载审计。</p><div class="dialog-actions"><button type="button" class="ghost-button" @click="rxDialog = false">取消</button><button type="submit" class="primary-small" :disabled="uploadingPrescription || !rxForm.fileKey">保存处方</button></div></form></div>
    <div v-if="promoterDialog" class="dialog-backdrop" @click.self="promoterDialog = false"><form class="dialog-card" @submit.prevent="submitPromoter"><div class="dialog-head"><h2>新增/编辑推广人</h2><button type="button" class="icon-button" @click="promoterDialog = false"><X :size="16" /></button></div><label>名称<input v-model="promoterForm.name" required /></label><label>身份<select v-model="promoterForm.promoterClass"><option value="sales">销售人员（高级会员）</option><option value="member">会员</option></select></label><label>绑定用户编号<input v-model="promoterForm.userId" placeholder="可选，绑定后可进入关系树" /></label><div class="dialog-actions"><button type="button" class="ghost-button" @click="promoterDialog = false">取消</button><button type="submit" class="primary-small">保存</button></div></form></div>
    <div v-if="customerDialog" class="dialog-backdrop" @click.self="customerDialog = false"><form class="dialog-card" @submit.prevent="submitCustomer"><div class="dialog-head"><h2>客户档案</h2><button type="button" class="icon-button" @click="customerDialog = false"><X :size="16" /></button></div><label>客户姓名<input v-model="customerForm.name" required /></label><label>所属推广人编号<input v-model="customerForm.promoter" /></label><label>标签（逗号分隔）<input v-model="customerForm.tags" /></label><div class="dialog-actions"><button type="button" class="ghost-button" @click="customerDialog = false">取消</button><button type="submit" class="primary-small">保存档案</button></div></form></div>
    <div v-if="bannerDialog" class="dialog-backdrop" @click.self="bannerDialog = false"><form class="dialog-card" @submit.prevent="submitBanner"><div class="dialog-head"><h2>新增/编辑轮播</h2><button type="button" class="icon-button" @click="bannerDialog = false"><X :size="16" /></button></div><label>标题<input v-model="bannerForm.title" required /></label><label>图片地址<input v-model="bannerForm.imageKey" required /></label><label>点击目标<input v-model="bannerForm.target" /></label><div class="dialog-actions"><button type="button" class="ghost-button" @click="bannerDialog = false">取消</button><button type="submit" class="primary-small">保存轮播</button></div></form></div>
    <div v-if="settingsDialog" class="dialog-backdrop" @click.self="settingsDialog = false"><form class="dialog-card" @submit.prevent="submitSettings"><div class="dialog-head"><h2>业务规则与公司资料</h2><button type="button" class="icon-button" @click="settingsDialog = false"><X :size="16" /></button></div><div class="dialog-grid"><label>满额包邮（元）<input v-model.number="settingsForm.shippingFreeThreshold" type="number" min="0" /></label><label>基础运费（元）<input v-model.number="settingsForm.shippingFee" type="number" min="0" /></label></div><div class="dialog-grid"><label>未支付取消（分钟）<input v-model.number="settingsForm.autoCancelMinutes" type="number" min="1" /></label><label>自动收货（天）<input v-model.number="settingsForm.autoReceiveDays" type="number" min="1" /></label></div><label>提现门槛（元）<input v-model.number="settingsForm.withdrawThreshold" type="number" min="0" /></label><div class="dialog-actions"><button type="button" class="ghost-button" @click="settingsDialog = false">取消</button><button type="submit" class="primary-small">保存规则</button></div></form></div>
